      x=urllib.request.urlopen(urllib.request.Request(BASE+path,headers={'Authorization':'Bearer '+t}),timeout=20);return json.loads(x.read())
    except urllib.error.HTTPError as e:
      if e.code in (401,403):
        t=json.load(urllib.request.urlopen(urllib.request.Request(BASE+'/token',method='POST')))['token'];continue
      if e.code==429:
        h=e.headers.get('Retry-After','1')
        try:w=float(h)
        except ValueError:w=max(0,(email.utils.parsedate_to_datetime(h)-datetime.datetime.now(datetime.timezone.utc)).total_seconds())
        print('rate limited; waiting',w,file=sys.stderr);time.sleep(w);continue
      print(e.code,e.read(),file=sys.stderr);time.sleep(1)
orders=json.load(open('/tmp/spring-recon/orders.json'))
seen=set(); distinct=[];duplicates=0
for page in orders:
 for o in page['items']:
  if o['id'] in seen:duplicates+=1
  else:seen.add(o['id']);distinct.append(o)
print('listings',sum(len(p['items']) for p in orders),'distinct',len(distinct),'duplicates',duplicates)
start=datetime.datetime.fromisoformat('2025-03-01T00:00:00+00:00');end=datetime.datetime.fromisoformat('2025-06-01T00:00:00+00:00')
qual=[]
for o in distinct:
 dt=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
 if o['status']=='shipped' and start<=dt<end:qual.append(o)
print('qualifying',len(qual),'customers',len(set(o['customer_id'] for o in qual)))
t=json.load(urllib.request.urlopen(urllib.request.Request(BASE+'/token',method='POST')))['token']
customers={}
for cid in sorted(set(o['customer_id'] for o in qual)):
 customers[cid]=get('/customers/'+cid)
with open('/tmp/spring-recon/customers.json','w') as f:json.dump(customers,f)
regions={'north':0,'south':0,'east':0,'west':0};amounts={};
for o in qual:
 c=customers[o['customer_id']]; n=o['amount_cents']*(100-c['discount_pct'])
 # positive amounts; half-up to cent via integer ratio
 discounted=(n+50)//100
 regions[c['region']]+=discounted
 amounts[o['id']]=discounted
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
print(result)
with open('/workspace/result.json','w') as f:json.dump(result,f,indent=2);f.write('\\n')
